import React, { useState, useRef } from 'react';
import { Canvas, useCamera, useLight, usePoint, Renderer } from '@react-three/fiber';
import { OrbitControls, Pickable, PickableProps } from '@react-three/drei';

const [isPickedUp, setIsPickedUp] = useState(false);
const [position, setPosition] = useState([0, 0, 0]);
const [rotation, setRotation] = useState([0, 0, 0]);
const [target, setTarget] = useState([0, 0, 0]);
const [remoteControl, setRemoteControl] = useState(
  new Pickable((handle, pickableProps) => ({
    handle,
    pickableProps,
    onPicking: () => setIsPickedUp(true),
    onReleasing: () => setIsPickedUp(false),
  }))
);

const remote = useRef(
  new Pickable((handle, pickableProps) => ({
    handle,
    pickableProps,
    onPicking: () => setIsPickedUp(true),
    onReleasing: () => setIsPickedUp(false),
  }))
);

function App() {
  const camera = useCamera();
  const light = useLight();
  const point = usePoint();
  const renderer = Renderer();
  const [position, setPosition] = useState([0, 0, 0]);
  const [rotation, setRotation] = useState([0, 0, 0]);
  const [target, setTarget] = useState([0, 0, 0]);
  const [isPickedUp, setIsPickedUp] = useState(false);
  const [remoteControl, setRemoteControl] = useState(
    new Pickable((handle, pickableProps) => ({
      handle,
      pickableProps,
      onPicking: () => setIsPickedUp(true),
      onReleasing: () => setIsPickedUp(false),
    }))
  );

  // 控制相机位置
  const [position, setPosition] = useState([0, 0, 0]);
  const [rotation, setRotation] = useState([0, 0, 0]);

  const handlePick = (e) => {
    if (e.button === 0) { // 鼠标左键
      setPosition([position.x, position.y, position.z]);
      setTarget([position.x, position.y, position.z]);
      setRotation([position.x, position.y, position.z]);
      setRemoteControl(remote);
    }
  };

  const handleRelease = (e) => {
    if (e.button === 0) { // 鼠标左键
      setRemoteControl(null);
      setIsPickedUp(false);
    }
  };

  const handleMove = (e) => {
    const newTarget = [e.clientX / window.innerWidth, e.clientY / window.innerHeight, 0];
    setTarget(newTarget);
  };

  const handleRotate = (e) => {
    const newRotation = [rotation.x + e.clientX / window.innerWidth, rotation.y + e.clientY / window.innerHeight, rotation.z];
    setRotation(newRotation);
  };

