  light.position.set([5, 5, 5]);
  light.intensity.set([0.5, 0.5, 0.5]);

  // Create a light
  const [light] = useLight();
  light.position.set([5, 5, 5]);
  light.intensity.set([0.5, 0.5, 0.5]);

  // Create a camera
  const [camera] = useCamera();
  camera.position.set([0, 0, 5]);
  camera.lookAt([0, 0, 0]);

  // Create a renderer
  const renderer = canvasRenderer({ antialias: true });

  return (
    <Canvas camera={camera} renderer={renderer} preserveAlpha={true}>
      <ambientLight intensity={0.3} />
      <pointLight position={[5, 5, 5]} />
      <meshBasic object={avatar} />
      <meshBasic object={remote} />
      <OrbitControls />
      <Pickable pickable={true}>
        <meshBasic object={remote} />
      </Pickable>
    </Canvas>
  );
}

export default [AvatarComponent];
